  `mobile` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `role` varchar(500) COLLATE utf8mb4_general_ci NOT NULL,
  `position` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` enum('active','inactive','on_leave','resigned') COLLATE utf8mb4_general_ci DEFAULT 'active',
  `join_date` date DEFAULT NULL,
  `phone` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `salary` decimal(15,2) NOT NULL DEFAULT '0.00',
  `bonus` decimal(10,2) DEFAULT '0.00',
  `payable_balance_iqd` decimal(20,2) DEFAULT '0.00',
  `payable_balance_usd` decimal(14,2) DEFAULT '0.00',
  `payable_balance` decimal(15,2) DEFAULT '0.00',
  `receivable_balance` decimal(15,2) DEFAULT '0.00',
  `notes` text COLLATE utf8mb4_general_ci,
  `salary_start_date` date DEFAULT NULL,
  `resignation_date` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
