/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_log_material_usage_insert` AFTER INSERT ON `sales` FOR EACH ROW BEGIN
    DECLARE v_black_sand_kg   DECIMAL(10,2);
    DECLARE v_brown_sand_kg   DECIMAL(10,2);
    DECLARE v_gravel_bin3_kg  DECIMAL(10,2);
    DECLARE v_gravel_bin4_kg  DECIMAL(10,2);
    DECLARE v_cement_cem1_kg  DECIMAL(10,2);
    DECLARE v_cement_cem2_kg  DECIMAL(10,2);
    DECLARE v_additive_kg     DECIMAL(10,2);

    -- ڕێژەکانی فۆرمۆلای کاتی داخڵکردن بخوێنە
    SELECT 
        black_sand_kg,
        brown_sand_kg,
        gravel_bin3_kg,
        gravel_bin4_kg,
        cement_cem1_kg,
        cement_cem2_kg,
        additive_kg
    INTO
        v_black_sand_kg,
        v_brown_sand_kg,
        v_gravel_bin3_kg,
        v_gravel_bin4_kg,
        v_cement_cem1_kg,
        v_cement_cem2_kg,
        v_additive_kg
    FROM concrete_formulas
    WHERE id = NEW.formula_id;

    -- گونجاندنی ڕێژەکان بە قەبارەی sale (متر سێجا)
    SET v_black_sand_kg  = IFNULL(v_black_sand_kg,  0) * NEW.quantity;
    SET v_brown_sand_kg  = IFNULL(v_brown_sand_kg,  0) * NEW.quantity;
    SET v_gravel_bin3_kg = IFNULL(v_gravel_bin3_kg, 0) * NEW.quantity;
    SET v_gravel_bin4_kg = IFNULL(v_gravel_bin4_kg, 0) * NEW.quantity;
    SET v_cement_cem1_kg = IFNULL(v_cement_cem1_kg, 0) * NEW.quantity;
    SET v_cement_cem2_kg = IFNULL(v_cement_cem2_kg, 0) * NEW.quantity;
    SET v_additive_kg    = IFNULL(v_additive_kg,    0) * NEW.quantity;

    -- تۆماری snapshot بۆ sale_materials
    INSERT INTO sale_materials (sale_id, material_type, kg) VALUES
        (NEW.id, 'black_sand',   v_black_sand_kg),
        (NEW.id, 'brown_sand',   v_brown_sand_kg),
        (NEW.id, 'gravel_bin3',  v_gravel_bin3_kg),
        (NEW.id, 'gravel_bin4',  v_gravel_bin4_kg),
        (NEW.id, 'cement_cem1',  v_cement_cem1_kg),
        (NEW.id, 'cement_cem2',  v_cement_cem2_kg),
        (NEW.id, 'additive',     v_additive_kg);
END */;;
DELIMITER ;
